export function cartTotal(lines) {
  const cents = lines.reduce((sum, line) => sum + line.price * line.qty * 100, 0);
  return Math.round(cents) / 100;
}

import { cartTotal } from '../../src/cart/total';

test('three items at 0.335 total 1.01', () => {
  expect(cartTotal([{ price: 0.335, qty: 3 }])).toBe(1.01);
});
